/* Employee relations, learning, engagement, reports, admin */

/* ---------------- CASES ---------------- */
const LADDER = ['Investigation','Hearing','Verbal warning','Written warning','Final written warning','Dismissal','No action'];
VIEWS.cases = () => {
  const k = tabOf('cs','list'); const vis = DB.cases.filter(c => isHR() || manageable().some(m=>m.id===c.emp));
  let body = '';
  if(k==='list') body = table([{h:'Case',f:c=>`<b>${c.id}</b>`},{h:'Type',f:c=>badge(c.type,c.type==='Grievance'?'pur':'info')},{h:'Employee',f:c=>esc(empName(c.emp))},{h:'Raised',f:c=>fmt(c.raised)},{h:'Stage',f:c=>esc(c.stage)},{h:'Owner',f:c=>esc(empName(c.owner))},{h:'Status',f:c=>statusBadge(c.status)},{h:'',cls:'right',f:c=>`<button class="btn sm" data-act="openCase" data-id="${c.id}">Open</button>`}], vis);
  else { const pe = DB.emps.filter(e=>vis.some(c=>c.emp===e.id) || (isHR() && e.disc.length)); body = `<div class="banner info">${ico('help')}<span>Disciplinary matrix: current warning level per employee from case records and history. Warning expiry periods are set by policy – HR to confirm.</span></div>` + table([{h:'Employee',f:e=>esc(e.name)},{h:'Department',f:e=>esc(e.depts.join(' / '))},...LADDER.slice(2,6).map(l=>({h:l.replace(' warning','').replace('Final written','Final'),cls:'right',f:e=>{ const n = e.disc.filter(d=>d.level===l).length + DB.cases.filter(c=>c.emp===e.id&&c.stage===l).length; return n?badge(String(n),l.startsWith('Final')?'bad':'warn'):'<span class="muted">–</span>'; }})),{h:'Dismissal',cls:'right',f:e=>DB.cases.filter(c=>c.emp===e.id&&c.stage==='Dismissal').length||'–'}], pe); }
  return pageHead('Grievance & Disciplinary','One case-management record per matter, with role-based visibility, timeline and legal documents.',`<button class="btn pri" data-act="newCase">${ico('plus')} Open case</button>`) + tabsHtml('cs',[['list','Cases'],['matrix','Disciplinary matrix']],'list') + `<div class="banner">${ico('lock')}<span>Restricted. Managers see cases for their team (without legal documents); HR sees all. Decisions require human approval and specialist HR/legal review.</span></div>` + body;
};
ACT.newCase = () => modal({title:'Open case',body:`<form id="cf2"><div class="fgrid"><div class="field"><label>Type</label><select name="t"><option>Disciplinary</option><option>Grievance</option></select></div><div class="field"><label>Employee</label><select name="e">${empOptions(isHR()?DB.emps.filter(e=>e.status==='active'):manageable().filter(e=>e.status==='active'))}</select></div><div class="field full"><label>Summary (factual, no opinions)</label><textarea name="s"></textarea></div></div><div id="cse" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Open case',cls:'pri',act:'saveCase'}]});
ACT.saveCase = el => submitOnce(el, () => { const f = $('#cf2'); if(f.s.value.trim().length<10){ const er = $('#cse'); er.textContent='Please enter a short factual summary (10+ characters).'; er.classList.add('show'); return; }
  const id = 'CS-'+(201+DB.cases.length); DB.cases.push({id,type:f.t.value,emp:f.e.value,raised:D.todayIso(),stage:'Investigation',owner:DB.emps.find(e=>e.role==='hr'||e.role==='admin').id,status:'Open',summary:f.s.value.trim(),legal:[],timeline:[{t:D.todayIso(),w:'Case opened by '+me().name}]}); notify(DB.emps.filter(e=>e.role==='hr'||e.role==='admin').map(e=>e.id), `New ${f.t.value.toLowerCase()} case ${id} opened.`, 'cases'); log('Case opened',id,f.e.value); saveDB(); closeModal(); render(); });
ACT.openCase = el => { const c = DB.cases.find(x=>x.id===el.dataset.id), e = emp(c.emp);
  modal({title:`${c.id} – ${c.type}`,size:'wide',body:`<div class="row sp"><div class="row">${av(e,40)}<div><b>${esc(e.name)}</b><div class="small muted">${esc(e.depts.join(' / '))}</div></div></div>${statusBadge(c.status)}</div><p>${esc(c.summary)}</p>
  <div class="grid g2"><div><h4>Timeline</h4><div class="tl" style="margin-top:10px">${c.timeline.slice().reverse().map(t=>`<div class="e"><b>${esc(t.w)}</b><div class="small muted">${fmt(t.t)}</div></div>`).join('')}</div></div>
  <div><h4>Stage</h4><p>${esc(c.stage)}</p>${isHR()?`<h4>Legal documentation</h4><div style="margin:6px 0">${c.legal.map(l=>`<span class="tag">${esc(l)}</span>`).join('')||'<span class="muted">None</span>'}</div>`:''}</div></div>
  ${isHR()&&c.status==='Open'?`<hr style="border:0;border-top:1px solid var(--line);margin:14px 0"><div class="fgrid"><div class="field"><label>Add timeline note</label><input id="ctn" placeholder="e.g. Hearing held"></div><div class="field"><label>Outcome / stage</label><select id="cst">${LADDER.map(l=>`<option ${l===c.stage?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Attach document (name)</label><input id="cdoc" placeholder="e.g. Outcome letter"></div></div>`:''}`,
  actions:[{label:'Close',act:'closeModal'},...(isHR()&&c.status==='Open'?[{label:'Close case',act:'caseClose',data:`data-id="${c.id}"`},{label:'Save update',cls:'pri',act:'caseSave',data:`data-id="${c.id}"`}]:[])]}); };
ACT.caseSave = el => { const c = DB.cases.find(x=>x.id===el.dataset.id), n = $('#ctn').value.trim(), s = $('#cst').value, d = $('#cdoc').value.trim(); if(s!==c.stage){ c.stage = s; c.timeline.push({t:D.todayIso(),w:'Stage: '+s}); if(['Verbal warning','Written warning','Final written warning'].includes(s)) emp(c.emp).disc.push({date:D.todayIso(),level:s,reason:c.summary.slice(0,60)}); } if(n) c.timeline.push({t:D.todayIso(),w:n}); if(d) c.legal.push(d); log('Case updated',c.id,c.emp); saveDB(); closeModal(); toast('Case updated','ok'); render(); };
ACT.caseClose = el => confirmBox('Close this case? The record and timeline remain in the audit trail.', () => { const c = DB.cases.find(x=>x.id===el.dataset.id); c.status='Closed'; c.timeline.push({t:D.todayIso(),w:'Case closed by '+me().name}); log('Case closed',c.id,c.emp); saveDB(); closeModal(); render(); }, 'Close case');

/* ---------------- HELPDESK ---------------- */
const TCATS = ['Salary Issues','Payslip Issues','Asset Requests','Queries'];
VIEWS.helpdesk = () => {
  DB.tickets.forEach(t => { if(!['Resolved','Escalated'].includes(t.status) && D.diff(t.raised,D.todayIso())>t.sla){ t.status='Escalated'; t.escalatedOn = D.todayIso(); notify(DB.emps.filter(e=>e.role==='admin').map(e=>e.id), `Ticket ${t.id} breached its SLA and was auto-escalated.`, 'helpdesk'); log('Ticket auto-escalated',t.id,t.emp); } }); saveDB();
  const list = DB.tickets.filter(t => isHR() || t.emp===SESSION.uid).sort((a,b)=>b.raised.localeCompare(a.raised));
  const res = DB.tickets.filter(t=>t.status==='Resolved' && t.resolved); const avg = res.length ? (res.reduce((s,t)=>s+D.diff(t.raised,t.resolved),0)/res.length).toFixed(1) : '—';
  return pageHead('Employee Helpdesk','Raise salary, payslip, asset and general queries. SLA tracking and auto-escalation apply.',`<button class="btn pri" data-act="newTicket">${ico('plus')} New ticket</button>`) +
  (isHR()?`<div class="grid g4" style="margin-bottom:16px">${[['Open',DB.tickets.filter(t=>t.status==='Open').length],['Escalated',DB.tickets.filter(t=>t.status==='Escalated').length],['Resolved',DB.tickets.filter(t=>t.status==='Resolved').length],['Avg days to resolve',avg]].map(([t,n])=>`<div class="card kpi"><span class="t">${t}</span><span class="v">${n}</span></div>`).join('')}</div>`:'') +
  table([{h:'Ticket',f:t=>`<b>${t.id}</b>`},{h:'Subject',f:t=>`${esc(t.subject)}<div class="small muted">${esc(t.cat)} · ${esc(empName(t.emp))}</div>`},{h:'Priority',f:t=>badge(t.pri,t.pri==='High'?'bad':t.pri==='Medium'?'warn':'')},{h:'Raised',f:t=>fmt(t.raised)},{h:'SLA',f:t=>t.status==='Resolved'?'—':(D.diff(t.raised,D.todayIso())>t.sla?badge('Breached','bad'):badge(`${t.sla-D.diff(t.raised,D.todayIso())}d left`,'ok'))},{h:'Status',f:t=>statusBadge(t.status)},{h:'',cls:'right',f:t=>`<button class="btn sm" data-act="openTicket" data-id="${t.id}">Open</button>`}], list);
};
ACT.newTicket = () => modal({title:'New ticket',body:`<form id="tf"><div class="fgrid"><div class="field"><label>Category</label><select name="c">${TCATS.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select name="p"><option>Low</option><option selected>Medium</option><option>High</option></select></div><div class="field full"><label>Subject</label><input name="s" maxlength="100"></div><div class="field full"><label>Details</label><textarea name="d"></textarea></div></div><p class="small muted">Do not include bank details or passwords.</p><div id="tfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Submit',cls:'pri',act:'saveTicket'}]});
ACT.saveTicket = el => submitOnce(el, () => { const f = $('#tf'); if(f.s.value.trim().length<4 || f.d.value.trim().length<5){ const er = $('#tfe'); er.textContent='Enter a subject and some details.'; er.classList.add('show'); return; }
  const id = 'T-'+(3001+DB.tickets.length); DB.tickets.push({id,cat:f.c.value,emp:SESSION.uid,subject:f.s.value.trim(),raised:D.todayIso(),sla:f.c.value==='Asset Requests'?5:3,status:'Open',pri:f.p.value,owner:DB.emps.find(e=>e.role==='hr').id,thread:[{w:me().name,t:D.todayIso(),m:f.d.value.trim()}]}); notify(DB.emps.filter(e=>e.role==='hr'||e.role==='admin').map(e=>e.id), `New ticket ${id}: ${f.s.value.trim()}`, 'helpdesk'); log('Ticket raised',id); saveDB(); closeModal(); toast('Ticket '+id+' raised','ok'); render(); });
ACT.openTicket = el => { const t = DB.tickets.find(x=>x.id===el.dataset.id);
  modal({title:`${t.id} – ${esc(t.subject)}`,size:'wide',body:`<div class="row wrap" style="margin-bottom:10px">${statusBadge(t.status)} ${badge(t.cat)} ${badge(t.pri+' priority')}</div><div class="list">${t.thread.map(m=>`<div class="li" style="align-items:flex-start"><div class="grow"><b>${esc(m.w)}</b> <span class="small muted">${fmt(m.t)}</span><div>${esc(m.m)}</div></div></div>`).join('')}</div>${t.status!=='Resolved'?`<div class="field" style="margin-top:12px"><label>Reply</label><textarea id="tr"></textarea></div>`:''}`,
  actions:[{label:'Close',act:'closeModal'},...(t.status!=='Resolved'?[{label:'Send reply',act:'ticketReply',data:`data-id="${t.id}"`},...(isHR()?[{label:'Resolve',cls:'ok',act:'ticketResolve',data:`data-id="${t.id}"`}]:[])]:[])]}); };
ACT.ticketReply = el => { const t = DB.tickets.find(x=>x.id===el.dataset.id), m = $('#tr').value.trim(); if(!m) return toast('Write a reply first.','bad'); t.thread.push({w:me().name,t:D.todayIso(),m}); notify(me().id===t.emp?DB.emps.filter(e=>e.role==='hr').map(e=>e.id):[t.emp], `New reply on ticket ${t.id}`, 'helpdesk'); saveDB(); closeModal(); render(); };
ACT.ticketResolve = el => { const t = DB.tickets.find(x=>x.id===el.dataset.id), m = $('#tr').value.trim(); if(m) t.thread.push({w:me().name,t:D.todayIso(),m}); t.status='Resolved'; t.resolved=D.todayIso(); notify(t.emp, `Ticket ${t.id} was resolved.`, 'helpdesk'); log('Ticket resolved',t.id,t.emp); saveDB(); closeModal(); render(); };

/* ---------------- DEDUCTIONS ---------------- */
VIEWS.deductions = () => {
  const list = DB.deductions.filter(d => isHR() || d.emp===SESSION.uid || manageable().some(m=>m.id===d.emp));
  return pageHead('Employee Deductions','Raised by HR or a line manager, approved by HR, acknowledged by the employee, then exported to payroll.',`${isHR()?`<button class="btn" data-act="exportDed">${ico('down')} Payroll export</button>`:''}${isMgr()?`<button class="btn pri" data-act="newDed">${ico('plus')} Raise deduction</button>`:''}`) +
  `<div class="banner">${ico('warn')}<span>Deductions from pay must follow the employment contract and the law. HR must verify authority before approval – this tool does not make that decision.</span></div>` +
  table([{h:'Ref',f:d=>d.id},{h:'Employee',f:d=>esc(empName(d.emp))},{h:'Type',f:d=>esc(d.type)+`<div class="small muted">${esc(d.desc)}</div>`},{h:'Date',f:d=>fmt(d.date)},{h:'Amount (ex-VAT n/a)',cls:'right',f:d=>gbp(d.amount)},{h:'Raised by',f:d=>esc(empName(d.by))},{h:'Acknowledged',f:d=>d.ack?badge('Yes','ok'):badge('No','warn')},{h:'Status',f:d=>statusBadge(d.status)},{h:'',cls:'right nowrap',f:d=>[ d.emp===SESSION.uid&&!d.ack?`<button class="btn sm" data-act="dedAck" data-id="${d.id}">Acknowledge</button>`:'', isHR()&&d.status==='Pending approval'?`<button class="btn sm ok" data-act="dedOk" data-id="${d.id}">Approve</button> <button class="btn sm bad" data-act="dedNo" data-id="${d.id}">Reject</button>`:'', `<button class="btn sm" data-act="dedHist" data-id="${d.id}">History</button>`].join(' ')}], list);
};
ACT.newDed = () => modal({title:'Raise deduction',body:`<form id="df"><div class="fgrid"><div class="field full"><label>Employee</label><select name="e">${empOptions(isHR()?DB.emps.filter(e=>e.status==='active'):manageable().filter(e=>e.status==='active'))}</select></div><div class="field"><label>Type</label><select name="t">${['Uniform replacement','Fuel card misuse','Overpayment recovery','Loan repayment','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Amount (£, GBP)</label><input type="number" name="a" min="0.01" step="0.01"></div><div class="field"><label>Date</label><input type="date" name="d" value="${D.todayIso()}"></div><div class="field full"><label>Description</label><textarea name="s"></textarea></div></div><div id="dfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Submit for approval',cls:'pri',act:'saveDed'}]});
ACT.saveDed = el => submitOnce(el, () => { const f = $('#df'), a = +f.a.value; if(!(a>0) || f.s.value.trim().length<5){ const er = $('#dfe'); er.textContent='Enter a positive amount and a description.'; er.classList.add('show'); return; }
  const id = 'D-'+String(DB.deductions.length+1).padStart(2,'0'); DB.deductions.push({id,emp:f.e.value,type:f.t.value,desc:f.s.value.trim(),date:f.d.value,amount:Math.round(a*100)/100,by:me().id,status:'Pending approval',ack:false,audit:[{t:nowStamp(),w:'Raised by '+me().name}]}); notify(f.e.value,'A deduction has been raised against you – please review and acknowledge.','deductions'); log('Deduction raised',id+' '+gbp(a),f.e.value); saveDB(); closeModal(); render(); });
ACT.dedAck = el => { const d = DB.deductions.find(x=>x.id===el.dataset.id); d.ack = true; (d.audit ||= []).push({t:nowStamp(),w:'Acknowledged by employee'}); log('Deduction acknowledged',d.id,d.emp); saveDB(); render(); };
ACT.dedOk = el => { const d = DB.deductions.find(x=>x.id===el.dataset.id); d.status='Approved – sent to payroll'; (d.audit ||= []).push({t:nowStamp(),w:'Approved by '+me().name}); log('Deduction approved',d.id,d.emp); saveDB(); render(); };
ACT.dedNo = el => { const d = DB.deductions.find(x=>x.id===el.dataset.id); d.status='Rejected'; (d.audit ||= []).push({t:nowStamp(),w:'Rejected by '+me().name}); log('Deduction rejected',d.id,d.emp); saveDB(); render(); };
ACT.dedHist = el => { const d = DB.deductions.find(x=>x.id===el.dataset.id); modal({title:'Audit history – '+d.id,body:`<div class="tl">${(d.audit||[{t:d.date,w:'Raised (migrated record)'}]).map(a=>`<div class="e"><b>${esc(a.w)}</b><div class="small muted">${fmtDT(a.t)}</div></div>`).join('')}</div>`,actions:[{label:'Close',act:'closeModal'}]}); };
ACT.exportDed = () => csvDownload('payroll_deductions',['Ref','Employee','Type','Date','Amount GBP','Acknowledged','Status'], DB.deductions.filter(d=>d.status.startsWith('Approved')).map(d=>[d.id,empName(d.emp),d.type,d.date,d.amount.toFixed(2),d.ack?'Yes':'No',d.status]));

/* ---------------- TRAINING ---------------- */
const certState = (e, c) => { const cert = DB.certs.filter(x=>x.emp===e.id && x.course===c.id).sort((a,b)=>b.date.localeCompare(a.date))[0]; if(!cert) return {s:'Missing',c:'bad'}; const exp = D.iso(new Date(+cert.date.slice(0,4), +cert.date.slice(5,7)-1+c.months, +cert.date.slice(8,10), 12)); const left = D.diff(D.todayIso(), exp); return left<0 ? {s:'Expired '+fmtS(exp),c:'bad'} : left<=60 ? {s:'Due '+fmtS(exp),c:'warn'} : {s:'Valid to '+fmtS(exp),c:'ok'}; };
VIEWS.training = () => {
  const tabs = [['reg','Register'],['ses','Sessions'],['lib','Video library'],['comp','Competencies'],['kpi','KPIs']], k = tabOf('tr','reg'); let body = '';
  const people = isMgr() ? visibleEmps().filter(e=>e.status==='active') : [me()];
  if(k==='reg') body = `<div class="toolbar"><span class="grow"></span>${isHR()?`<button class="btn" data-act="addCert">${ico('plus')} Record certificate</button><button class="btn" data-act="addCourse">${ico('plus')} Add course</button>`:''}</div><div class="tw"><table class="t"><thead><tr><th>Employee</th>${DB.courses.map(c=>`<th>${esc(c.name)}${c.mandatory?' *':''}</th>`).join('')}</tr></thead><tbody>${people.map(e=>`<tr><td><b>${esc(e.name)}</b></td>${DB.courses.map(c=>{ const s = certState(e,c); return `<td>${badge(s.s,s.c)}</td>`; }).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:8px">* Mandatory. Validity periods (${DB.courses.map(c=>c.name+' '+c.months+'m').join(', ')}) are configurable placeholders.</p>`;
  if(k==='ses') body = `<div class="toolbar"><span class="grow"></span>${isHR()?`<button class="btn pri" data-act="newSession">${ico('plus')} Schedule training</button>`:''}</div><div class="grid g2">${DB.sessions.filter(s=>isHR()||s.invited.includes(SESSION.uid)||isMgr()).map(s=>{ const c = DB.courses.find(x=>x.id===s.course), inv = s.invited.includes(SESSION.uid); return `<div class="card"><div class="row sp"><b>${esc(c.name)}</b>${badge(fmtS(s.date)+' '+s.time,'info')}</div><div class="small muted" style="margin:4px 0 10px">${esc(s.loc)} · ${esc(s.trainer)}</div><div class="small">Invited (${s.invited.length}): ${s.invited.map(i=>esc(empName(i))).join(', ')}</div><div class="small" style="margin-top:6px">Declarations signed: <b>${Object.keys(s.declared).length}</b> / ${s.invited.length}</div><div class="row wrap" style="margin-top:12px"><button class="btn sm" data-act="sesIcs" data-id="${s.id}">${ico('cal')} Add to calendar</button>${inv&&!s.declared[SESSION.uid]?`<button class="btn sm pri" data-act="declare" data-id="${s.id}">Sign trainee declaration</button>`:inv?badge('Declaration signed','ok'):''}</div></div>`; }).join('')||'<div class="empty">No sessions scheduled.</div>'}</div>`;
  if(k==='lib') body = `<div class="toolbar"><span class="grow"></span>${isHR()?`<button class="btn" data-act="remindVideos">${ico('bell')} Weekly reminder to non-viewers</button><button class="btn pri" data-act="addVideo">${ico('up')} Add video</button>`:''}</div><div class="grid g3">${DB.videos.map(v=>`<div class="card"><div style="aspect-ratio:16/9;background:linear-gradient(135deg,var(--navy),var(--navy2));border-radius:10px;display:flex;align-items:center;justify-content:center;color:#fff;margin-bottom:10px;cursor:pointer" data-act="playVideo" data-id="${v.id}">${ico('video')}</div><b>${esc(v.title)}</b><div class="small muted">${esc(v.cat)} · ${v.len}</div><div class="row sp" style="margin-top:8px">${v.seen[SESSION.uid]?badge('Viewed','ok'):badge('Not viewed','warn')}<span class="small muted">${Object.keys(v.seen).length} views</span></div></div>`).join('')}</div>`;
  if(k==='comp') body = `<div class="toolbar"><span class="grow"></span>${isMgr()?`<button class="btn pri" data-act="newComp">${ico('plus')} New assessment</button>`:''}</div>${table([{h:'Employee',f:c=>esc(empName(c.emp))},{h:'Job description',f:c=>esc(c.jd)},{h:'Date',f:c=>fmt(c.date)},{h:'Scores',f:c=>Object.entries(c.scores).map(([k,v])=>`<span class="tag">${esc(k)} ${v}</span>`).join('')},{h:'Average',f:c=>'<b>'+(Object.values(c.scores).reduce((a,b)=>a+b,0)/Object.keys(c.scores).length).toFixed(1)+'</b>'},{h:'Training plan',f:c=>esc(c.plan)}], DB.competencies.filter(c=>isHR()||c.emp===SESSION.uid||manageable().some(m=>m.id===c.emp)))}`;
  if(k==='kpi'){ DB.kpis ||= []; body = `<div class="toolbar"><span class="grow"></span>${isMgr()?`<button class="btn pri" data-act="newKpi">${ico('plus')} Add KPI</button>`:''}</div><div class="grid g2">${DB.kpis.filter(x=>isHR()||x.emp===SESSION.uid||manageable().some(m=>m.id===x.emp)).map(x=>{ const p = Math.min(100,Math.round(x.actual/x.target*100)); return `<div class="card"><div class="row sp"><b>${esc(x.title)}</b>${badge(p+'%',p>=100?'ok':p>=60?'warn':'bad')}</div><div class="small muted">${esc(empName(x.emp))} · ${esc(x.period)}</div><div class="prog ${p>=100?'g':p>=60?'o':'r'}" style="margin:10px 0"><i style="width:${p}%"></i></div><div class="row sp small"><span>Actual ${x.actual}</span><span>Target ${x.target}</span></div>${isMgr()?`<button class="btn sm" style="margin-top:8px" data-act="kpiUpd" data-id="${x.id}">Update actual</button>`:''}</div>`; }).join('')||'<div class="empty">No KPIs set.</div>'}</div>`; }
  return pageHead('Training & Development','Mandatory training register, scheduling with auto-invites, video library, competencies and KPIs.') + tabsHtml('tr',tabs,'reg') + body;
};
ACT.addCourse = () => modal({title:'Add course',body:`<form id="cof"><div class="fgrid"><div class="field full"><label>Course name</label><input name="n"></div><div class="field"><label>Validity (months)</label><input type="number" name="m" value="12" min="1" max="120"></div><div class="field"><label>Mandatory</label><select name="x"><option value="1">Yes</option><option value="0">No</option></select></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Add',cls:'pri',act:'saveCourse'}]});
ACT.saveCourse = () => { const f = $('#cof'); if(f.n.value.trim().length<3) return toast('Enter a name.','bad'); DB.courses.push({id:uid('tc'),name:f.n.value.trim(),mandatory:f.x.value==='1',months:+f.m.value||12,link:'—'}); saveDB(); closeModal(); render(); };
ACT.addCert = () => modal({title:'Record certificate',body:`<form id="ctf"><div class="fgrid"><div class="field"><label>Employee</label><select name="e">${empOptions(DB.emps.filter(e=>e.status==='active'))}</select></div><div class="field"><label>Course</label><select name="c">${DB.courses.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Completed on</label><input type="date" name="d" value="${D.todayIso()}" max="${D.todayIso()}"></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'saveCert'}]});
ACT.saveCert = () => { const f = $('#ctf'); if(!f.d.value) return toast('Pick a date.','bad'); DB.certs.push({emp:f.e.value,course:f.c.value,date:f.d.value}); log('Certificate recorded',f.c.value,f.e.value); saveDB(); closeModal(); render(); };
ACT.newSession = () => modal({title:'Schedule training',size:'wide',body:`<form id="sf2"><div class="fgrid"><div class="field"><label>Course</label><select name="c">${DB.courses.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Trainer / provider</label><input name="t"></div><div class="field"><label>Date</label><input type="date" name="d" min="${D.todayIso()}"></div><div class="field"><label>Time</label><input type="time" name="h" value="10:00"></div><div class="field full"><label>Location / Teams link</label><input name="l"></div><div class="field full"><label>Invite employees (auto-invites sent on save)</label><div class="grid g3" style="max-height:170px;overflow:auto">${DB.emps.filter(e=>e.status==='active').map(e=>`<label class="row" style="margin:0;gap:6px;font-weight:500"><input type="checkbox" style="width:auto" name="inv" value="${e.id}"> ${esc(e.name)}</label>`).join('')}</div></div></div><div id="sfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Schedule & invite',cls:'pri',act:'saveSession'}]});
ACT.saveSession = el => submitOnce(el, () => { const f = $('#sf2'), inv = $$('input[name=inv]:checked',f).map(x=>x.value), er = $('#sfe'); if(!f.d.value || !f.l.value.trim() || !inv.length){ er.textContent='Choose a date, a location and at least one attendee.'; er.classList.add('show'); return; }
  const s = {id:uid('ts'),course:f.c.value,date:f.d.value,time:f.h.value,loc:f.l.value.trim(),invited:inv,trainer:f.t.value.trim()||'TBC',declared:{}}; DB.sessions.push(s); const c = DB.courses.find(x=>x.id===s.course); notify(inv, `You are invited to ${c.name} on ${fmt(s.date)} at ${s.time}. Please sign the trainee declaration.`, 'training'); log('Training scheduled',`${c.name} ${s.date} (${inv.length} invited)`); saveDB(); closeModal(); toast(`Invites sent to ${inv.length} employee(s)`,'ok'); render(); });
ACT.sesIcs = el => { const s = DB.sessions.find(x=>x.id===el.dataset.id), c = DB.courses.find(x=>x.id===s.course), d = s.date.replace(/-/g,''), t = s.time.replace(':',''); fileDownload('training_'+c.name.replace(/\W/g,'_')+'.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//PFG HRMS//EN\r\nBEGIN:VEVENT\r\nUID:${s.id}@pfg-hrms\r\nDTSTAMP:${d}T000000Z\r\nDTSTART:${d}T${t}00\r\nDURATION:PT2H\r\nSUMMARY:${c.name}\r\nLOCATION:${s.loc}\r\nEND:VEVENT\r\nEND:VCALENDAR`,'text/calendar'); };
ACT.declare = el => modal({title:'Trainee declaration',body:`<p class="small">I confirm that I attended and completed this training, that I understand its content, and that I will follow the procedures taught.</p><div class="field"><label>Type your full name to sign</label><input id="dcn" placeholder="${esc(me().name)}"></div>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Sign declaration',cls:'pri',act:'declSave',data:`data-id="${el.dataset.id}"`}]});
ACT.declSave = el => { if($('#dcn').value.trim().toLowerCase()!==me().name.toLowerCase()) return toast('Type your name exactly as shown.','bad'); const s = DB.sessions.find(x=>x.id===el.dataset.id); s.declared[SESSION.uid] = nowStamp(); log('Training declaration signed',s.id); saveDB(); closeModal(); render(); };
ACT.addVideo = () => modal({title:'Add training / company video',body:`<form id="vf"><div class="fgrid"><div class="field full"><label>Title</label><input name="t"></div><div class="field"><label>Category</label><select name="c"><option>Induction</option><option>Health & Safety</option><option>Portal</option><option>Company</option></select></div><div class="field"><label>Length (mm:ss)</label><input name="l" placeholder="5:00"></div><div class="field full"><label>Video link (Stream / SharePoint / YouTube) or file (≤ 1 MB demo)</label><input name="u" placeholder="https://…"><input type="file" accept="video/*" data-chg="vidFile" style="margin-top:8px"></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Add',cls:'pri',act:'saveVideo'}]});
CHG.vidFile = el => { const f = el.files[0]; if(!f) return; if(f.size>1024*1024){ toast('Prototype limit is 1 MB – use a link for larger files.','bad'); el.value=''; return; } const r = new FileReader(); r.onload = () => { window.__vid = r.result; toast('File ready'); }; r.readAsDataURL(f); };
ACT.saveVideo = () => { const f = $('#vf'), u = f.u.value.trim(); if(f.t.value.trim().length<3) return toast('Enter a title.','bad'); if(u && !/^https:\/\//.test(u)) return toast('Links must start with https://','bad'); if(!u && !window.__vid) return toast('Add a link or a file.','bad'); DB.videos.push({id:uid('v'),title:f.t.value.trim(),cat:f.c.value,len:f.l.value||'—',src:u||window.__vid,seen:{}}); window.__vid = null; log('Video added',f.t.value); saveDB(); closeModal(); render(); };
ACT.playVideo = el => { const v = DB.videos.find(x=>x.id===el.dataset.id); v.seen[SESSION.uid] = D.todayIso(); saveDB(); const play = v.src.startsWith('data:video') ? `<video controls autoplay style="width:100%;border-radius:10px" src="${v.src}"></video>` : v.src ? `<p>Opens the video in a new tab:</p><a class="btn pri" target="_blank" rel="noopener noreferrer" href="${esc(v.src)}">Open video</a>` : `<div class="empty">Sample entry – no media attached yet.</div>`; modal({title:esc(v.title),body:play,actions:[{label:'Close',act:'closeModal'}]}); };
ACT.remindVideos = () => { let n = 0; DB.videos.forEach(v => DB.emps.filter(e=>e.status==='active' && !v.seen[e.id]).forEach(e => { notify(e.id, `Reminder: please watch “${v.title}”.`, 'training'); n++; })); log('Video reminders sent',n+' reminders'); saveDB(); toast(`${n} reminders sent`,'ok'); };
ACT.newComp = () => { const ppl = manageable().filter(e=>e.status==='active'); modal({title:'Competency assessment',body:`<form id="cpf"><div class="fgrid"><div class="field"><label>Employee</label><select name="e">${empOptions(ppl)}</select></div><div class="field"><label>Linked job description</label><input name="jd" placeholder="Job title"></div>${['Customer focus','Commercial awareness','Communication','Planning'].map(k=>`<div class="field"><label>${k} (1–5)</label><select name="${k}">${[1,2,3,4,5].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}<div class="field full"><label>Linked training plan</label><input name="p"></div></div><p class="small muted">Rate role-relevant behaviours using evidence only.</p></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Submit',cls:'pri',act:'saveComp'}]}); };
ACT.saveComp = () => { const f = $('#cpf'); if(!f.jd.value.trim()) return toast('Enter the linked job description.','bad'); DB.competencies.push({id:uid('cp'),emp:f.e.value,by:me().id,date:D.todayIso(),jd:f.jd.value.trim(),scores:Object.fromEntries(['Customer focus','Commercial awareness','Communication','Planning'].map(k=>[k,+f[k].value])),plan:f.p.value.trim()||'—'}); log('Competency assessment',f.e.value,f.e.value); saveDB(); closeModal(); render(); };
ACT.newKpi = () => modal({title:'Add KPI',body:`<form id="kf"><div class="fgrid"><div class="field full"><label>Employee</label><select name="e">${empOptions(manageable().filter(e=>e.status==='active'))}</select></div><div class="field full"><label>KPI</label><input name="t"></div><div class="field"><label>Target</label><input type="number" name="g" min="1" step="any"></div><div class="field"><label>Actual</label><input type="number" name="a" min="0" step="any" value="0"></div><div class="field full"><label>Period</label><input name="p" value="${MONTHS[D.today().getMonth()]} ${D.today().getFullYear()}"></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'saveKpi'}]});
ACT.saveKpi = () => { const f = $('#kf'); if(!f.t.value.trim() || !(+f.g.value>0)) return toast('Enter a KPI and a positive target.','bad'); (DB.kpis ||= []).push({id:uid('k'),emp:f.e.value,title:f.t.value.trim(),target:+f.g.value,actual:+f.a.value||0,period:f.p.value}); saveDB(); closeModal(); render(); };
ACT.kpiUpd = el => { const k = DB.kpis.find(x=>x.id===el.dataset.id); const v = prompt('New actual value', k.actual); if(v!==null && !isNaN(+v) && +v>=0){ k.actual = +v; saveDB(); render(); } };

/* ---------------- POLICIES ---------------- */
VIEWS.policies = (param) => {
  if(param && DB.policies.find(p=>p.id===param)) setTimeout(()=>{ history.replaceState(null,'','#/policies'); policyModal(param); },0);
  const q = ST.f.pq||'', cat = ST.f.pcat||'', list = DB.policies.filter(p => (!cat||p.cat===cat) && (!q || (p.title+p.body).toLowerCase().includes(q.toLowerCase())));
  const acked = id => DB.ack[id]?.[SESSION.uid];
  return pageHead('Policies & SOPs','Published versions, read-receipts and reminders. Ask the policy assistant to find the right policy.',`${isHR()?`<button class="btn pri" data-act="newPolicy">${ico('plus')} Publish policy / SOP</button>`:''}`) +
  `<div class="card" style="margin-bottom:16px;background:linear-gradient(135deg,#f3f6ff,#fff)"><h3><span class="l">${ico('search')} Policy assistant</span></h3><div class="row"><input type="search" id="pbot" placeholder="Type a word, e.g. carry-over, sickness, probation, COSHH" value="${esc(q)}" data-inp="pq" style="flex:1"><button class="btn pri" data-act="pbotGo">Find</button></div><p class="small muted" style="margin:8px 0 0">Searches published text and shows the relevant sentences with links. This is keyword search, not legal advice.</p>${q?`<div style="margin-top:12px">${list.map(p=>{ const sents = p.body.split(/(?<=\.)\s+/).filter(s=>s.toLowerCase().includes(q.toLowerCase())); return `<div class="li" style="align-items:flex-start"><div class="grow"><a href="#" data-act="openPolicy" data-id="${p.id}"><b>${esc(p.title)}</b></a> <span class="small muted">v${p.ver}</span>${sents.map(s=>`<div class="small">“…${esc(s).replace(new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'ig'),m=>`<mark>${m}</mark>`)}”</div>`).join('')}</div></div>`; }).join('')||'<div class="muted">No matching policy. Contact HR.</div>'}</div>`:''}</div>
  <div class="toolbar"><select data-chg="pcat"><option value="">All types</option><option ${cat==='Policy'?'selected':''}>Policy</option><option ${cat==='SOP'?'selected':''}>SOP</option></select></div>` +
  table([{h:'Document',f:p=>`<b>${esc(p.title)}</b><div class="small muted">${p.cat} · owner ${esc(p.owner)} · audience ${esc(p.aud)}</div>`},{h:'Version',f:p=>'v'+p.ver},{h:'Published',f:p=>fmt(p.date)},{h:'Acknowledged',f:p=>isHR()?`${Object.keys(DB.ack[p.id]||{}).length} / ${DB.emps.filter(e=>e.status==='active').length}`:(acked(p.id)?badge('Read '+fmtS(acked(p.id)),'ok'):badge('Action needed','warn'))},{h:'',cls:'right nowrap',f:p=>`<button class="btn sm" data-act="openPolicy" data-id="${p.id}">Open</button>${isHR()?` <button class="btn sm" data-act="remindPolicy" data-id="${p.id}">Remind</button>`:''}`}], list);
};
CHG.pq = el => { ST.f.pq = el.value; render(); const f = $('#pbot'); f.focus(); f.setSelectionRange(f.value.length,f.value.length); };
CHG.pcat = el => { ST.f.pcat = el.value; render(); };
ACT.pbotGo = () => { ST.f.pq = $('#pbot').value.trim(); render(); };
function policyModal(id){ const p = DB.policies.find(x=>x.id===id), a = DB.ack[id]?.[SESSION.uid];
  modal({title:esc(p.title),size:'wide',body:`<div class="row wrap" style="margin-bottom:10px">${badge(p.cat)} ${badge('v'+p.ver,'info')} <span class="small muted">Published ${fmt(p.date)} · owner ${esc(p.owner)}</span></div><p style="line-height:1.7">${esc(p.body)}</p>${isHR()?`<h4 style="margin-top:14px">Read receipts</h4><div class="small">${DB.emps.filter(e=>e.status==='active').map(e=>`<span class="tag" style="${DB.ack[id]?.[e.id]?'background:var(--ok-l);color:var(--ok)':''}">${esc(e.name)} ${DB.ack[id]?.[e.id]?'✓':'–'}</span>`).join('')}</div>`:''}`,actions:[{label:'Close',act:'closeModal'},a?{label:'Acknowledged '+fmt(a),act:'closeModal'}:{label:'I have read and understood this',cls:'pri',act:'ack',data:`data-id="${id}"`}]}); }
ACT.openPolicy = el => policyModal(el.dataset.id);
ACT.ack = el => { (DB.ack[el.dataset.id] ||= {})[SESSION.uid] = D.todayIso(); log('Policy acknowledged',el.dataset.id); saveDB(); closeModal(); toast('Acknowledgement recorded','ok'); render(); };
ACT.remindPolicy = el => { const p = DB.policies.find(x=>x.id===el.dataset.id), t = DB.emps.filter(e=>e.status==='active' && !DB.ack[p.id]?.[e.id]); notify(t.map(e=>e.id), `Please read and acknowledge: ${p.title}`, 'policies'); log('Policy reminder',p.title+' → '+t.length); saveDB(); toast(`Reminder sent to ${t.length} employee(s)`,'ok'); };
ACT.newPolicy = () => modal({title:'Publish policy / SOP',size:'wide',body:`<form id="pf"><div class="fgrid"><div class="field full"><label>Title (re-use an existing title to publish a new version)</label><input name="t"></div><div class="field"><label>Type</label><select name="c"><option>Policy</option><option>SOP</option></select></div><div class="field"><label>Version</label><input name="v" value="1.0"></div><div class="field"><label>Owner</label><input name="o" value="HR"></div><div class="field"><label>Audience</label><select name="a"><option>All</option><option>Managers</option><option>HR</option></select></div><div class="field full"><label>Content</label><textarea name="b" style="min-height:140px"></textarea></div></div><div id="pfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Publish',cls:'pri',act:'savePolicy'}]});
ACT.savePolicy = () => { const f = $('#pf'), er = $('#pfe'); if(f.t.value.trim().length<3 || f.b.value.trim().length<20 || !/^\d+(\.\d+)*$/.test(f.v.value.trim())){ er.textContent='Title, content (20+ characters) and a numeric version (e.g. 1.1) are required.'; er.classList.add('show'); return; }
  const ex = DB.policies.find(p=>p.title.toLowerCase()===f.t.value.trim().toLowerCase()); if(ex){ ex.ver = f.v.value.trim(); ex.body = f.b.value.trim(); ex.date = D.todayIso(); DB.ack[ex.id] = {}; } else DB.policies.push({id:uid('p'),title:f.t.value.trim(),cat:f.c.value,ver:f.v.value.trim(),date:D.todayIso(),status:'Published',owner:f.o.value,aud:f.a.value,body:f.b.value.trim()});
  notify(DB.emps.filter(e=>e.status==='active').map(e=>e.id), `New ${f.c.value.toLowerCase()} published: ${f.t.value.trim()}`, 'policies'); log('Policy published',f.t.value+' v'+f.v.value); saveDB(); closeModal(); toast('Published and circulated','ok'); render(); };

/* ---------------- FORMS ---------------- */
VIEWS.forms = () => pageHead('Forms','Build simple forms (like MS Forms), share them in the portal and view responses.',`${isMgr()?`<button class="btn pri" data-act="newForm">${ico('plus')} Create form</button>`:''}`) +
  `<div class="grid g3">${DB.forms.map(f=>`<div class="card"><b>${esc(f.title)}</b><div class="small muted" style="margin:4px 0 10px">${esc(f.desc)}</div><div class="small">${f.fields.length} questions · ${f.responses.length} responses</div><div class="row wrap" style="margin-top:12px"><button class="btn sm pri" data-act="fillForm" data-id="${f.id}">${f.responses.some(r=>r.who===SESSION.uid)?'Submitted – view':'Fill in'}</button>${isMgr()?`<button class="btn sm" data-act="formResp" data-id="${f.id}">Responses</button>`:''}</div></div>`).join('')}</div>`;
ACT.newForm = () => { window.__ff = []; modal({title:'Create form',size:'wide',body:`<form id="fb" onsubmit="return false"><div class="fgrid"><div class="field"><label>Title</label><input name="t"></div><div class="field"><label>Description</label><input name="d"></div></div><h4>Questions</h4><div id="fq" class="small muted" style="margin:6px 0">No questions yet.</div><div class="fgrid"><div class="field"><label>Question</label><input id="qq1"></div><div class="field"><label>Type</label><select id="qt"><option value="text">Short text</option><option value="choice">Choice</option><option value="rating">Rating 1–5</option><option value="check">Checkbox</option></select></div><div class="field full"><label>Choices (comma-separated, for Choice)</label><input id="qo"></div></div><button class="btn sm" data-act="addQ">${ico('plus')} Add question</button></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Create form',cls:'pri',act:'saveForm'}]}); };
ACT.addQ = () => { const l = $('#qq1').value.trim(), t = $('#qt').value, o = $('#qo').value.trim(); if(!l) return toast('Enter the question.','bad'); if(t==='choice' && o.split(',').filter(x=>x.trim()).length<2) return toast('Give at least two choices.','bad'); window.__ff.push({k:'q'+window.__ff.length,label:l,type:t,opts:o}); $('#qq1').value=''; $('#qo').value=''; $('#fq').innerHTML = window.__ff.map((q,i)=>`${i+1}. ${esc(q.label)} <span class="tag">${q.type}</span>`).join('<br>'); };
ACT.saveForm = () => { const f = $('#fb'); if(f.t.value.trim().length<3 || !window.__ff.length) return toast('Add a title and at least one question.','bad'); DB.forms.push({id:uid('f'),title:f.t.value.trim(),desc:f.d.value.trim(),by:SESSION.uid,fields:window.__ff,responses:[]}); log('Form created',f.t.value); saveDB(); closeModal(); render(); };
ACT.fillForm = el => { const f = DB.forms.find(x=>x.id===el.dataset.id), r = f.responses.find(x=>x.who===SESSION.uid);
  modal({title:esc(f.title),body:`<p class="muted">${esc(f.desc)}</p><form id="ff" onsubmit="return false">${f.fields.map(q=>`<div class="field"><label>${esc(q.label)}</label>${q.type==='text'?`<textarea name="${q.k}" ${r?'disabled':''}>${esc(r?.a[q.k]||'')}</textarea>`:q.type==='choice'?`<select name="${q.k}" ${r?'disabled':''}>${q.opts.split(',').map(o=>`<option ${r?.a[q.k]===o.trim()?'selected':''}>${esc(o.trim())}</option>`).join('')}</select>`:q.type==='rating'?`<select name="${q.k}" ${r?'disabled':''}>${[5,4,3,2,1].map(n=>`<option ${r?.a[q.k]==n?'selected':''}>${n}</option>`).join('')}</select>`:`<select name="${q.k}" ${r?'disabled':''}><option>No</option><option ${r?.a[q.k]==='Yes'?'selected':''}>Yes</option></select>`}</div>`).join('')}</form>`,actions:[{label:'Close',act:'closeModal'},...(r?[]:[{label:'Submit',cls:'pri',act:'submitForm',data:`data-id="${f.id}"`}])]}); };
ACT.submitForm = el => submitOnce(el, () => { const f = DB.forms.find(x=>x.id===el.dataset.id); if(f.responses.some(r=>r.who===SESSION.uid)) return; const a = {}; f.fields.forEach(q=>a[q.k] = $('#ff')[q.k].value); f.responses.push({who:SESSION.uid,t:D.todayIso(),a}); log('Form submitted',f.title); saveDB(); closeModal(); toast('Thank you – response recorded','ok'); render(); });
ACT.formResp = el => { const f = DB.forms.find(x=>x.id===el.dataset.id); modal({title:'Responses – '+esc(f.title),size:'wide',body:table([{h:'Who',f:r=>esc(empName(r.who))},{h:'Date',f:r=>fmt(r.t)},...f.fields.map(q=>({h:esc(q.label),f:r=>esc(r.a[q.k])}))],f.responses,{empty:'No responses yet.'}),actions:[{label:'Close',act:'closeModal'},{label:'Export CSV',cls:'pri',act:'formCsv',data:`data-id="${f.id}"`}]}); };
ACT.formCsv = el => { const f = DB.forms.find(x=>x.id===el.dataset.id); csvDownload('form_'+f.title.replace(/\W/g,'_'),['Who','Date',...f.fields.map(q=>q.label)],f.responses.map(r=>[empName(r.who),r.t,...f.fields.map(q=>r.a[q.k])])); };

/* ---------------- NOTICE BOARD ---------------- */
VIEWS.noticeboard = () => {
  const tabs = [['news','News & events'],['promo','Promotions'],['rec','Recognition'],['gal','Memories']], k = tabOf('nb','news'); DB.views ||= {};
  const post = n => { (DB.views[n.id] ||= []); if(!DB.views[n.id].includes(SESSION.uid)) DB.views[n.id].push(SESSION.uid);
    return `<div class="card"><div class="row sp wrap"><div class="row">${n.who?av(n.who,42):`<div class="kicon" style="background:#e2f4f8;color:var(--blue)">${ico(n.kind==='Event'?'cal':'flag')}</div>`}<div><b style="font-size:15px">${esc(n.title)}</b><div class="small muted">${badge(n.kind)} ${fmt(n.date)} · ${esc(n.by)}</div></div></div>${isHR()?`<span class="small muted">${DB.views[n.id].length} read · ${reactCount('news-'+n.id)} reactions</span>`:''}</div><p style="margin:12px 0">${esc(n.body)}</p><div class="row sp wrap">${reactBar('news-'+n.id)}<span class="row">${n.who===SESSION.uid&&!n.thanks?`<button class="btn sm" data-act="thank" data-id="${n.id}">Reply with thanks</button>`:''}${n.thanks?`<span class="small"><b>${esc(empName(n.who))}:</b> “${esc(n.thanks)}”</span>`:''}</span></div></div>`; };
  let body = '';
  if(k==='news') body = `<div class="grid">${DB.news.filter(n=>n.kind!=='Promotion').map(post).join('')||'<div class="empty">No news.</div>'}</div>`;
  if(k==='promo') body = `<div class="grid">${DB.news.filter(n=>n.kind==='Promotion').map(post).join('')||'<div class="empty">No promotions.</div>'}</div>`;
  if(k==='rec') body = `<div class="toolbar"><span class="grow"></span>${isMgr()?`<button class="btn pri" data-act="newRec">${ico('plus')} Nominate</button>`:''}${isHR()?`<button class="btn" data-act="recMail">${ico('mail')} Send monthly reaction summaries</button>`:''}</div><div class="grid g2">${DB.recognition.map(r=>{ const e = emp(r.who); return `<div class="card"><div class="row">${e?av(e,48):''}<div><b>${esc(e?e.name:r.who)}</b><div>${badge(r.kind+' of the Month '+r.month,'pur')}</div></div></div><p>${esc(r.why)}</p><div class="row sp">${reactBar('rec-'+r.id)}<span class="small muted">${reactCount('rec-'+r.id)} reactions this month</span></div></div>`; }).join('')}</div>`;
  if(k==='gal') body = `<div class="toolbar"><span class="grow"></span>${isHR()?`<button class="btn pri" data-act="newMem">${ico('plus')} Add memory</button>`:''}</div><div class="grid g3">${DB.gallery.map(g=>`<div class="card">${g.img?`<img src="${g.img}" alt="" style="width:100%;border-radius:10px;aspect-ratio:16/10;object-fit:cover">`:`<div style="aspect-ratio:16/10;border-radius:10px;background:linear-gradient(135deg,#dbe5fb,#f3e8ff);display:flex;align-items:center;justify-content:center;color:var(--blue)">${ico('award')}</div>`}<b style="display:block;margin-top:10px">${esc(g.title)}</b><div class="small muted">${g.year} · ${esc(g.note)}</div></div>`).join('')}</div>`;
  saveDB();
  return pageHead('Notice Board','Company news, promotions, recognition and official memories.',`${isHR()?`<button class="btn pri" data-act="newPost">${ico('plus')} New post</button>`:''}`) + tabsHtml('nb',tabs,'news') + body;
};
ACT.thank = el => modal({title:'Thank you reply',body:`<div class="field"><label>Your message (also emailed to HR – simulated)</label><textarea id="thx" maxlength="240"></textarea></div>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Send',cls:'pri',act:'thankSave',data:`data-id="${el.dataset.id}"`}]});
ACT.thankSave = el => { const m = $('#thx').value.trim(); if(m.length<3) return toast('Write a short message.','bad'); DB.news.find(n=>n.id===el.dataset.id).thanks = m; log('Promotion thank-you',''); saveDB(); closeModal(); render(); };
ACT.newPost = () => modal({title:'New notice',body:`<form id="npf"><div class="fgrid"><div class="field"><label>Type</label><select name="k"><option>News</option><option>Event</option><option>Promotion</option></select></div><div class="field"><label>Promoted employee (for promotions)</label><select name="w"><option value="">—</option>${empOptions(DB.emps.filter(e=>e.status==='active'))}</select></div><div class="field full"><label>Headline</label><input name="t" maxlength="120"></div><div class="field full"><label>Message</label><textarea name="b"></textarea></div><div class="field full"><label class="row" style="gap:8px;margin:0"><input type="checkbox" name="m" style="width:auto" checked> Send email notification with portal link (simulated)</label></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Publish',cls:'pri',act:'savePost'}]});
ACT.savePost = el => submitOnce(el, () => { const f = $('#npf'); if(f.t.value.trim().length<4 || f.b.value.trim().length<5) return toast('Enter a headline and message.','bad'); DB.news.unshift({id:uid('n'),kind:f.k.value,title:f.t.value.trim(),by:me().name,date:D.todayIso(),body:f.b.value.trim(),who:f.k.value==='Promotion'&&f.w.value?f.w.value:undefined}); if(f.m.checked) notify(DB.emps.filter(e=>e.status==='active').map(e=>e.id), `${f.k.value}: ${f.t.value.trim()}`, 'noticeboard'); log('Notice published',f.t.value); saveDB(); closeModal(); toast('Published','ok'); render(); });
ACT.newRec = () => modal({title:'Nominate for recognition',body:`<form id="nrf"><div class="fgrid"><div class="field"><label>Employee</label><select name="w">${empOptions(visibleEmps().filter(e=>e.id!==SESSION.uid))}</select></div><div class="field full"><label>Why? (specific, evidence-based)</label><textarea name="y"></textarea></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Post',cls:'pri',act:'saveRec'}]});
ACT.saveRec = () => { const f = $('#nrf'); if(f.y.value.trim().length<10) return toast('Please give a reason (10+ characters).','bad'); DB.recognition.push({id:uid('r'),who:f.w.value,by:SESSION.uid,month:D.todayIso().slice(0,7),why:f.y.value.trim(),kind:'Employee'}); notify(f.w.value,'You have been recognised on the Notice Board.','noticeboard'); saveDB(); closeModal(); render(); };
ACT.recMail = () => { DB.recognition.forEach(r => { if(emp(r.who)) notify(r.who, `Your recognition this month received ${reactCount('rec-'+r.id)} reaction(s).`, 'noticeboard'); }); log('Recognition summaries sent',''); saveDB(); toast('Monthly summaries sent (simulated email)','ok'); };
ACT.newMem = () => modal({title:'Add official memory',body:`<form id="mf"><div class="fgrid"><div class="field"><label>Title</label><input name="t"></div><div class="field"><label>Year</label><input type="number" name="y" min="1990" max="${D.today().getFullYear()}" value="${D.today().getFullYear()}"></div><div class="field full"><label>Note</label><input name="n"></div><div class="field full"><label>Photo (≤ 300 KB)</label><input type="file" accept="image/*" data-chg="memImg"></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Add',cls:'pri',act:'saveMem'}]});
CHG.memImg = el => { const f = el.files[0]; if(!f) return; if(f.size>300*1024){ toast('Image larger than 300 KB.','bad'); el.value=''; return; } const r = new FileReader(); r.onload = () => window.__mem = r.result; r.readAsDataURL(f); };
ACT.saveMem = () => { const f = $('#mf'); if(f.t.value.trim().length<3) return toast('Enter a title.','bad'); DB.gallery.unshift({id:uid('g'),title:f.t.value.trim(),year:f.y.value,note:f.n.value.trim()||'Official memory',img:window.__mem||null}); window.__mem = null; saveDB(); closeModal(); render(); };

/* ---------------- CHAT ---------------- */
VIEWS.chat = () => {
  const u = me(), threads = isHR() ? [...new Set(DB.chat.map(m=>m.thread))] : [u.id]; const cur = isHR() ? (ST.f.thread && threads.includes(ST.f.thread) ? ST.f.thread : threads[0]) : u.id;
  const msgs = DB.chat.filter(m=>m.thread===cur);
  return pageHead('Chat with HR','Secure message thread between staff and HR. Do not share passwords or bank details.') +
  `<div class="grid" style="grid-template-columns:${isHR()?'260px 1fr':'1fr'};align-items:start">${isHR()?`<div class="card"><h3>Conversations</h3>${threads.map(t=>`<div class="li" style="cursor:pointer;${t===cur?'background:var(--blue-l);border-radius:8px;padding:8px':''}" data-act="thread" data-id="${t}">${av(t,30)}<b>${esc(empName(t))}</b></div>`).join('')||'<div class="empty">No conversations.</div>'}</div>`:''}
  <div class="card"><div style="min-height:280px;max-height:50vh;overflow:auto;display:flex;flex-direction:column;gap:10px;padding:4px">${msgs.map(m=>`<div style="align-self:${m.from===u.id?'flex-end':'flex-start'};max-width:75%;background:${m.from===u.id?'var(--navy)':'#eef1f7'};color:${m.from===u.id?'#fff':'inherit'};padding:10px 14px;border-radius:14px"><div class="small" style="opacity:.7">${esc(empName(m.from))} · ${fmtDT(m.t)}</div>${esc(m.text)}</div>`).join('')||'<div class="empty">Start a conversation with HR.</div>'}</div>
  <div class="row" style="margin-top:12px"><input id="cmsg" maxlength="500" placeholder="Write a message…" onkeydown="if(event.key==='Enter')ACT.send(this)"><button class="btn pri" data-act="send">Send</button></div></div></div>`;
};
ACT.thread = el => { ST.f.thread = el.dataset.id; render(); };
ACT.send = () => { const i = $('#cmsg'), t = i.value.trim(); if(!t) return; const th = isHR() ? (ST.f.thread || DB.chat[0]?.thread) : SESSION.uid; if(!th) return; DB.chat.push({id:uid('m'),thread:th,from:SESSION.uid,t:nowStamp(),text:t}); notify(isHR()?th:DB.emps.filter(e=>e.role==='hr').map(e=>e.id), `New chat message from ${me().name}`, 'chat'); saveDB(); render(); $('#cmsg')?.focus(); };
AFTER.chat = () => { const b = $('.card div[style*="overflow:auto"]'); if(b) b.scrollTop = b.scrollHeight; };

/* ---------------- REPORTS ---------------- */
const scopeEmps = (o={}) => (isHR() ? DB.emps : manageable()).filter(e => (o.leavers || e.status==='active') && (!o.dept || e.depts.includes(o.dept)) && (!o.region || e.region===o.region));
const inRange = (d,a,b) => (!a||d>=a) && (!b||d<=b);
const age = e => Math.floor(D.diff(e.dob,D.todayIso())/365.25), svc = e => D.diff(e.start, e.leaveDate||D.todayIso())/365.25;
const REPORTS = [
 {id:'summary',name:'Employee summary',d:'Headcount by company, region and contract',run:p=>{ const l = scopeEmps(p), by = {}; l.forEach(e=>{ const k = e.company+'|'+e.region+'|'+e.contract; by[k] = (by[k]||0)+1; }); return {h:['Company','Region','Contract','Headcount'],r:Object.entries(by).map(([k,n])=>[...k.split('|'),n])}; }},
 {id:'demo',name:'Demographics',d:'Age band, length of service and region (aggregated)',run:p=>{ const l = scopeEmps(p), rows = []; [['Under 25',0,24],['25–34',25,34],['35–44',35,44],['45–54',45,54],['55+',55,200]].forEach(([n,a,b])=>rows.push(['Age',n,l.filter(e=>age(e)>=a&&age(e)<=b).length])); [['Under 1 year',0,1],['1–3 years',1,3],['3–5 years',3,5],['5–10 years',5,10],['10+ years',10,100]].forEach(([n,a,b])=>rows.push(['Service',n,l.filter(e=>svc(e)>=a&&svc(e)<b).length])); REGIONS.forEach(r=>rows.push(['Region',r,l.filter(e=>e.region===r).length])); return {h:['Dimension','Band','Employees'],r:rows}; }},
 {id:'attr',name:'Attrition',d:'Leavers, reasons and rate in the period',run:p=>{ const f = p.from||D.iso(D.add(D.today(),-365)), t = p.to||D.todayIso(); const lv = DB.exits.filter(x=>inRange(x.last,f,t) && scopeEmps({...p,leavers:true}).some(e=>e.id===x.emp)); const hc = scopeEmps({...p,leavers:true}).length; return {h:['Employee','Type','Reason','Last day','Tenure (yrs)'],r:lv.map(x=>[empName(x.emp),x.type,x.reason,x.last,svc(emp(x.emp)).toFixed(1)]).concat([['Attrition rate','','',`${hc?(lv.length/hc*100).toFixed(2):'0.00'}%`,'']])}; }},
 {id:'att',name:'Attendance summary',d:'Working days by absence type in a custom date range',run:p=>{ const f = p.from||D.iso(D.add(D.today(),-30)), t = p.to||D.todayIso(); const types = Object.keys(LT).filter(k=>k!=='HALF'); return {h:['Employee','Department',...types.map(k=>LT[k].code),'Total'],r:scopeEmps(p).map(e=>{ const c = types.map(k=>DB.leave.filter(l=>l.emp===e.id&&l.type===k&&l.status==='approved').reduce((s,l)=>s+recDays({...l,start:l.start<f?f:l.start,end:l.end>t?t:l.end},e.region)*(l.end<f||l.start>t?0:1),0)); return [e.name,e.depts.join(' / '),...c.map(num1),num1(c.reduce((a,b)=>a+b,0))]; })}; }},
 {id:'brad',name:'Bradford Factor',d:'Rolling 52 weeks: spells² × days',run:p=>({h:['Employee','Department','Spells','Days','Score','Stage'],r:scopeEmps(p).map(e=>({e,b:bradford(e.id)})).filter(x=>x.b.spells).sort((a,b)=>b.b.score-a.b.score).map(x=>[x.e.name,x.e.depts.join(' / '),x.b.spells,num1(x.b.days),x.b.score,bradLevel(x.b.score)[0]])})},
 {id:'absd',name:'Absence – detailed',d:'Every absence record in the range',run:p=>{ const f = p.from||D.iso(D.add(D.today(),-90)), t = p.to||D.todayIso(), ids = new Set(scopeEmps({...p,leavers:true}).map(e=>e.id)); return {h:['Employee','Type','From','To','Days','Status','Notes'],r:DB.leave.filter(l=>ids.has(l.emp)&&l.type!=='HOL'&&inRange(l.start,f,t)).map(l=>[empName(l.emp),LT[l.type].name,l.start,l.end,num1(recDays(l,emp(l.emp).region)),l.status,LT[l.type].sick&&!isHR()?'(restricted)':l.note])}; }},
 {id:'hol',name:'Holidays – approved, unapproved & remaining',d:'Per employee with percentage used',run:p=>{ return {h:['Employee','Entitlement','Approved','Unapproved (pending)','Remaining','% used'],r:scopeEmps(p).map(e=>{ const b = balance(e,curLY(e)), ap = b.taken+b.upcoming; return [e.name,num1(b.total),num1(ap),num1(b.pending),num1(b.remaining),(b.total?ap/b.total*100:0).toFixed(2)+'%']; })}; }},
 {id:'accr',name:'Accrual',d:'Accrued to date vs taken',run:p=>{ return {h:['Employee','Region','Start','Entitlement','Accrued to date','Taken','Booked','Balance now'],r:scopeEmps(p).map(e=>{ const b = balance(e,curLY(e)); return [e.name,e.region,e.start,num1(b.total),num1(b.acc),num1(b.taken),num1(b.upcoming),num1(b.acc-b.taken)]; })}; }},
 {id:'month',name:'Monthly employee report',d:'Starters, leavers and absence for a month',run:p=>{ const m = p.month||D.todayIso().slice(0,7), l = scopeEmps({...p,leavers:true}); return {h:['Measure','Value'],r:[['Month',m],['Starters',l.filter(e=>e.start.startsWith(m)).length],['Leavers',l.filter(e=>(e.leaveDate||'').startsWith(m)).length],['Sickness days',num1(DB.leave.filter(x=>LT[x.type].sick&&l.some(e=>e.id===x.emp)).reduce((s,x)=>{ let n=0; for(let d=D.parse(x.start);D.iso(d)<=x.end;d=D.add(d,1)){ if(D.iso(d).startsWith(m)) n+=dayValue(x,D.iso(d),emp(x.emp).region); } return s+n; },0))],['Holiday days',num1(DB.leave.filter(x=>x.type==='HOL'&&x.status==='approved'&&l.some(e=>e.id===x.emp)).reduce((s,x)=>{ let n=0; for(let d=D.parse(x.start);D.iso(d)<=x.end;d=D.add(d,1)){ if(D.iso(d).startsWith(m)) n+=dayValue(x,D.iso(d),emp(x.emp).region); } return s+n; },0))]]}; }},
 {id:'comp',name:'HR compliance',d:'RTW, probation, policy acknowledgements and training',run:p=>{ const l = scopeEmps(p); const pol = DB.policies.filter(x=>x.aud==='All'); return {h:['Employee','RTW status','Policies acknowledged','Mandatory training'],r:l.map(e=>{ const rc = DB.rtwChecks.find(x=>x.emp===e.id), left = rc&&rc.expiry?D.diff(D.todayIso(),rc.expiry):null; const mt = DB.courses.filter(c=>c.mandatory); return [e.name,!rc?'No check recorded':left===null?'Valid (no expiry)':left<0?'EXPIRED':left<=60?`Due in ${left} days`:'Valid',`${pol.filter(x=>DB.ack[x.id]?.[e.id]).length}/${pol.length}`,`${mt.filter(c=>certState(e,c).c==='ok').length}/${mt.length} valid`]; })}; }},
 {id:'start',name:'Start & leave dates',d:'Joiners and leavers',run:p=>({h:['Employee','Department','Start','Leaving'],r:scopeEmps({...p,leavers:true}).map(e=>[e.name,e.depts.join(' / '),e.start,e.leaveDate||''])})},
 {id:'emerg',name:'Emergency contacts',d:'Restricted to HR',hr:1,run:p=>({h:['Employee','Contact','Relationship','Phone'],r:scopeEmps(p).map(e=>[e.name,e.emergency.name,e.emergency.rel,e.emergency.phone])})},
 {id:'mood',name:'Mood (anonymised)',d:'Daily mood totals – no individual data',hr:1,run:()=>{ const by = {}; DB.mood.forEach(m=>{ (by[m.date] ||= {})[m.v] = (by[m.date][m.v]||0)+1; }); return {h:['Date',...MOODS.map(m=>m[1])],r:Object.entries(by).sort().map(([d,v])=>[d,...MOODS.map(m=>v[m[1]]||0)])}; }},
 {id:'sick',name:'Sickness',d:'Spells and days by employee, last 52 weeks',run:p=>({h:['Employee','Department','Spells','Days','Fri/Mon days','Total days'],r:scopeEmps(p).map(e=>({e,b:bradford(e.id),f:fridayMonday(e.id)})).filter(x=>x.b.spells).map(x=>[x.e.name,x.e.depts.join(' / '),x.b.spells,num1(x.b.days),x.f.fm,x.f.tot])})}
];
VIEWS.reports = () => {
  const k = tabOf('rp','lib');
  let body = '';
  if(k==='lib') body = `<div class="grid g3">${REPORTS.filter(r=>!r.hr||isHR()).map(r=>`<div class="card"><b>${esc(r.name)}</b><p class="small muted" style="margin:6px 0 12px">${esc(r.d)}</p><button class="btn sm pri" data-act="runReport" data-id="${r.id}">Open</button></div>`).join('')}</div>`;
  if(k==='run'){ const r = REPORTS.find(x=>x.id===ST.f.rid) || REPORTS[0], p = ST.f.rp ||= {}; const out = r.run(p);
    body = `<div class="row" style="margin-bottom:10px"><button class="btn sm" data-act="tab" data-v="rp" data-k="lib">← Reports</button><h3>${esc(r.name)}</h3></div><div class="toolbar"><select data-chg="rpF" data-k="dept"><option value="">All departments</option>${deptOptions(p.dept)}</select><select data-chg="rpF" data-k="region"><option value="">All regions</option>${REGIONS.map(x=>`<option ${p.region===x?'selected':''}>${x}</option>`).join('')}</select>From <input type="date" data-chg="rpF" data-k="from" value="${p.from||''}" style="width:150px"> To <input type="date" data-chg="rpF" data-k="to" value="${p.to||''}" style="width:150px">${isHR()?`<label class="row small" style="gap:6px"><input type="checkbox" style="width:auto" data-chg="rpL" ${p.leavers?'checked':''}> Include leavers</label>`:''}<span class="grow"></span><button class="btn pri" data-act="rpExport">${ico('down')} Export CSV</button></div><p class="small muted">Dates apply to range-based reports. ${out.r.length} rows.</p>` + table(out.h.map((h,i)=>({h:esc(h),f:row=>esc(row[i])})), out.r, {empty:'No data for the selected filters.'}); window.__rp = out; }
  if(k==='bi') body = biCard();
  if(k==='build'){ const ds = ST.f.bds||'emp', cols = BUILD[ds].cols, sel = ST.f.bcols ||= cols.slice(0,5).map(c=>c[0]), p = ST.f.bp ||= {};
    const rows = BUILD[ds].rows(p); body = `<div class="card" style="margin-bottom:16px"><div class="fgrid"><div class="field"><label>Data set</label><select data-chg="bds">${Object.entries(BUILD).map(([k,v])=>`<option value="${k}" ${k===ds?'selected':''}>${v.name}</option>`).join('')}</select></div><div class="field"><label>Filter department</label><select data-chg="bF" data-k="dept"><option value="">All</option>${deptOptions(p.dept)}</select></div></div><label style="font-size:12px;font-weight:600">Columns</label><div class="row wrap" style="margin-top:6px">${cols.map(([k,l])=>`<label class="row" style="margin:0;gap:5px;font-weight:500"><input type="checkbox" style="width:auto" data-chg="bcol" value="${k}" ${sel.includes(k)?'checked':''}> ${l}</label>`).join('')}</div><div class="row" style="margin-top:12px"><button class="btn pri" data-act="bExport">${ico('down')} Export CSV</button><button class="btn" data-act="bSave">Save report</button></div></div>${DB.savedReports.length?`<div class="row wrap" style="margin-bottom:10px"><b>Saved:</b>${DB.savedReports.map(s=>`<button class="btn sm" data-act="bLoad" data-id="${s.id}">${esc(s.name)}</button>`).join('')}</div>`:''}` + table(cols.filter(c=>sel.includes(c[0])).map(c=>({h:c[1],f:r=>esc(c[2](r))})), rows, {empty:'No rows.'}); }
  return pageHead('Reports & Analytics','Standard reports, advanced filters, custom report builder and CSV export (Power BI ready).') + tabsHtml('rp',[['lib','Report library'],['run','Run report'],['build','Custom builder'],['bi','Power BI exports']],'lib') + body;
};
ACT.runReport = el => { ST.f.rid = el.dataset.id; ST.f.rp = {}; ST.tab.rp = 'run'; render(); };
CHG.rpF = el => { (ST.f.rp ||= {})[el.dataset.k] = el.value; render(); }; CHG.rpL = el => { ST.f.rp.leavers = el.checked; render(); };
ACT.rpExport = () => { const r = REPORTS.find(x=>x.id===ST.f.rid); csvDownload('report_'+r.id, window.__rp.h, window.__rp.r); };
const BUILD = {
  emp:{name:'Employees',cols:[['name','Name',e=>e.name],['title','Job title',e=>e.title],['dept','Department(s)',e=>e.depts.join(' / ')],['company','Company',e=>e.company],['region','Region',e=>e.region],['mgr','Manager',e=>empName(e.mgr)],['start','Start date',e=>e.start],['contract','Contract',e=>e.contract],['fte','FTE',e=>e.fte],['svc','Service (yrs)',e=>svc(e).toFixed(1)],['status','Status',e=>e.status]],rows:p=>scopeEmps({dept:p.dept,leavers:true})},
  leave:{name:'Leave & absence records',cols:[['emp','Employee',l=>empName(l.emp)],['type','Type',l=>LT[l.type].name],['from','From',l=>l.start],['to','To',l=>l.end],['days','Working days',l=>num1(recDays(l,emp(l.emp).region))],['status','Status',l=>l.status],['half','Half day',l=>l.half||'']],rows:p=>{ const ids = new Set(scopeEmps({dept:p.dept,leavers:true}).map(e=>e.id)); return DB.leave.filter(l=>ids.has(l.emp)); }},
  bal:{name:'Leave balances',cols:[['name','Employee',x=>x.e.name],['ent','Entitlement',x=>num1(x.b.total)],['taken','Taken',x=>num1(x.b.taken)],['up','Booked',x=>num1(x.b.upcoming)],['pend','Pending',x=>num1(x.b.pending)],['rem','Remaining',x=>num1(x.b.remaining)]],rows:p=>scopeEmps({dept:p.dept}).map(e=>({e,b:balance(e,curLY(e))}))}
};
CHG.bds = el => { ST.f.bds = el.value; ST.f.bcols = null; render(); }; CHG.bF = el => { ST.f.bp[el.dataset.k] = el.value; render(); };
CHG.bcol = el => { const s = new Set(ST.f.bcols); el.checked ? s.add(el.value) : s.delete(el.value); ST.f.bcols = [...s]; render(); };
ACT.bExport = () => { const ds = ST.f.bds||'emp', c = BUILD[ds].cols.filter(x=>ST.f.bcols.includes(x[0])); if(!c.length) return toast('Select at least one column.','bad'); csvDownload('custom_'+ds, c.map(x=>x[1]), BUILD[ds].rows(ST.f.bp).map(r=>c.map(x=>x[2](r)))); };
ACT.bSave = () => { const n = prompt('Name this report'); if(n && n.trim()){ DB.savedReports.push({id:uid('sr'),name:n.trim(),ds:ST.f.bds||'emp',cols:ST.f.bcols,p:ST.f.bp}); saveDB(); render(); } };
ACT.bLoad = el => { const s = DB.savedReports.find(x=>x.id===el.dataset.id); ST.f.bds = s.ds; ST.f.bcols = s.cols.slice(); ST.f.bp = {...s.p}; render(); };

/* ---------------- ACTIVITY LOG ---------------- */
VIEWS.activity = () => {
  const f = ST.f.al ||= {q:'',region:'',dept:''}; const list = DB.log.filter(a => (!f.q || (a.user+a.action+a.detail).toLowerCase().includes(f.q.toLowerCase())) && (!f.region||a.region===f.region) && (!f.dept||a.dept.includes(f.dept)) && (!f.from||a.t.slice(0,10)>=f.from) && (!f.to||a.t.slice(0,10)<=f.to));
  window.__al = list;
  return pageHead('Activity Log','Searchable audit of who did what, filterable by region and department.',`<button class="btn" data-act="alExport">${ico('down')} Export</button>`) +
  `<div class="toolbar"><input type="search" class="search" placeholder="Search user, action, detail" value="${esc(f.q)}" data-inp="alQ" id="alq"><select data-chg="alF" data-k="region"><option value="">All regions</option>${REGIONS.map(r=>`<option ${f.region===r?'selected':''}>${r}</option>`).join('')}</select><select data-chg="alF" data-k="dept"><option value="">All departments</option>${deptOptions(f.dept)}</select><input type="date" data-chg="alF" data-k="from" value="${f.from||''}" style="width:150px" aria-label="From"><input type="date" data-chg="alF" data-k="to" value="${f.to||''}" style="width:150px" aria-label="To"><span class="muted small">${list.length} entries</span></div>` +
  table([{h:'When',f:a=>fmtDT(a.t)},{h:'User',f:a=>esc(a.user)},{h:'Action',f:a=>`<b>${esc(a.action)}</b>`},{h:'Detail',f:a=>esc(a.detail)},{h:'Region',f:a=>a.region},{h:'Department',f:a=>esc(a.dept)}], list.slice(0,300), {max:560});
};
CHG.alQ = el => { ST.f.al.q = el.value; render(); const f = $('#alq'); f.focus(); f.setSelectionRange(f.value.length,f.value.length); };
CHG.alF = el => { ST.f.al[el.dataset.k] = el.value; render(); };
ACT.alExport = () => csvDownload('activity_log',['When','User','Action','Detail','Region','Department'], window.__al.map(a=>[a.t,a.user,a.action,a.detail,a.region,a.dept]));

/* ---------------- SETTINGS ---------------- */
VIEWS.settings = () => pageHead('Settings','Policy parameters. Changes are logged. Confirm values against approved HR policy.') +
  `<div class="grid g2"><div class="card"><h3>Leave quotas (days per year, full-time)</h3><form id="sq" onsubmit="return false">${REGIONS.map(r=>`<div class="field"><label>${r} annual leave entitlement</label><input type="number" name="${r}" min="0" max="60" step="0.5" value="${DB.settings.quota[r]}"></div>`).join('')}<div class="field"><label>Bradford Factor thresholds (stage 1 / 2 / final)</label><div class="row"><input type="number" name="b0" value="${DB.settings.bradford[0]}" min="1"><input type="number" name="b1" value="${DB.settings.bradford[1]}" min="1"><input type="number" name="b2" value="${DB.settings.bradford[2]}" min="1"></div></div><button class="btn pri" data-act="saveSettings">Save settings</button></form><p class="small muted" style="margin-top:10px">${esc(DB.settings.note)}</p></div>
  <div class="card"><h3>Prototype data</h3><p class="muted">All data lives in this browser only. Nothing is sent to a server.</p><button class="btn" data-act="exportAll">${ico('down')} Export all data (JSON)</button> <button class="btn bad" data-act="resetDemo">Reset sample data</button></div></div>`;
ACT.saveSettings = () => { const f = $('#sq'), q = {UK:+f.UK.value, PK:+f.PK.value}, b = [+f.b0.value,+f.b1.value,+f.b2.value]; if(q.UK<0||q.PK<0||isNaN(q.UK)||isNaN(q.PK)) return toast('Quotas must be zero or more.','bad'); if(!(b[0]<b[1] && b[1]<b[2])) return toast('Thresholds must increase: stage 1 < stage 2 < final.','bad'); DB.settings.quota = q; DB.settings.bradford = b; log('Settings changed',`Quota UK ${q.UK} / PK ${q.PK}; Bradford ${b.join('/')}`); saveDB(); toast('Settings saved','ok'); };
ACT.exportAll = () => { fileDownload('pfg_hrms_export.json', JSON.stringify(DB,null,1), 'application/json'); log('Full data export',''); };

