VIEWS.brs = () => { const n = s => BRS.filter(r=>r[4].startsWith(s)).length;
  return pageHead('BRS Coverage','Traceability of Appendix 17 requirements (HR-001 to HR-056) to this prototype.',`<button class="btn" data-act="brsExport">${ico('down')} Export</button>`) +
  `<div class="banner info">${ico('help')}<span><b>VERIFIED FACT:</b> source is PFG_HRMS_BRS_v1.0 (01 March 2026). <b>ASSUMPTION:</b> “Built” means working in this browser prototype with sample data; it is not production-ready and still needs UAT, SSO, a server database and integrations (Azure AD, Paxton, Power BI, Xero/Paycircle).</span></div>
  <div class="grid g4" style="margin-bottom:16px">${[['Built',n('Built')],['Prototype',n('Prototype')+n('Partial')],['Planned',n('Planned')],['Total',BRS.length]].map(([t,v])=>`<div class="card kpi"><span class="t">${t}</span><span class="v">${v}</span></div>`).join('')}</div>` +
  table([{h:'ID',f:r=>`<b>${r[0]}</b>`},{h:'Requirement',f:r=>esc(r[1])},{h:'Priority',f:r=>badge(r[2],r[2]==='High'?'bad':r[2]==='Medium'?'warn':'')},{h:'Where',f:r=>esc(r[3])},{h:'Status',f:r=>badge(r[4],r[4].startsWith('Built')?'ok':r[4].startsWith('Planned')?'':'warn')}], BRS); };
ACT.brsExport = () => csvDownload('brs_coverage',['ID','Requirement','Priority','Where','Status'],BRS);
